def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Fast counters
    opp_c = 0
    my_c = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    for m, o in history:
        if o == 'C':
            opp_c += 1
        if m == 'C':
            my_c += 1
        if m == 'C':
            if o == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if o == 'C':
                dc += 1
            else:
                dd += 1

    my_last, opp_last = history[-1]

    # Opening: probe with C, retaliate once if defected.
    if n == 1:
        return 'C' if opp_last == 'C' else 'D'
    if n == 2:
        if opp_last == 'D':
            return 'D'
        return 'C'

    # All-out exploitation if opponent is nearly always defecting.
    if opp_c <= 1 and n >= 6:
        return 'D'
    if opp_c <= max(1, n // 6) and n >= 12:
        return 'D'

    # Pure cooperation partner: cooperate until endgame.
    if opp_c == n:
        if n >= 96:
            return 'D'
        return 'C'

    # Detect recent opponent behavior windows.
    k = 6 if n > 6 else n
    recent_opp_def = 0
    recent_my_def = 0
    start = n - k
    for i in range(start, n):
        if history[i][1] == 'D':
            recent_opp_def += 1
        if history[i][0] == 'D':
            recent_my_def += 1

    recent_opp_coop = k - recent_opp_def

    # Long streak of opponent defections: mostly defect, occasional olive branch.
    streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        streak += 1
        i -= 1
    if streak >= 5:
        if n < 92 and streak < 12 and rng.random() < 0.07:
            return 'C'
        return 'D'
    if streak >= 3:
        if n < 90 and rng.random() < 0.12:
            return 'C'
        return 'D'

    # Long streak of opponent cooperation: cooperate, occasional probe.
    cstreak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'C':
        cstreak += 1
        i -= 1
    if cstreak >= 8:
        if n < 88 and rng.random() < 0.045:
            return 'D'
        return 'C'

    # Recent heavy defection: punish.
    if recent_opp_def >= 4:
        if recent_opp_def >= 6:
            return 'D'
        if opp_last == 'D':
            return 'D'
        if rng.random() < 0.35:
            return 'D'
        return 'C'

    # Recent heavy cooperation: sustain cooperation.
    if recent_opp_def == 0:
        if n >= 94:
            return 'D' if opp_c * 10 >= n * 7 else 'C'
        if n >= 40 and rng.random() < 0.02:
            return 'D'
        return 'C'

    # Endgame: exploit a sufficiently cooperative opponent.
    if n >= 94:
        if opp_c * 2 >= n:
            return 'D'
        if opp_last == 'C':
            return 'D'
        return 'C'

    # Late game: shift toward exploitation as match end approaches.
    if n >= 85:
        if opp_c * 3 >= n * 2:
            return 'D'
        if opp_last == 'D':
            return 'D'
        return 'C'

    # Tit-for-tat-like core with forgiveness based on cooperation rate.
    if opp_last == 'C':
        if my_last == 'D' and recent_opp_def >= 2:
            return 'C'
        return 'C'
    else:
        if recent_opp_def >= 2:
            return 'D'
        if opp_c * 4 >= n * 3:
            if rng.random() < 0.65:
                return 'C'
            return 'D'
        if rng.random() < 0.25:
            return 'C'
        return 'D'
